    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    # A complete row identifies the stripe color to use as the reference.
    stripe_colors = {
        row[0] for row in grid
        if row[0] != background and all(cell == row[0] for cell in row)
    }
    for stripe_color in stripe_colors:
        for r, row in enumerate(grid):
            if row[0] != stripe_color:
                continue
            run_end = 0
            while run_end < width and row[run_end] == stripe_color:
                run_end += 1
            if run_end == 0 or run_end == width:
                continue
            # Match the demonstrated pattern: one contiguous stripe prefix,
            # followed only by background; mark its first trailing cell.
            if all(cell == background for cell in row[run_end:]):
                out[r][run_end] = 1
                return out
    return out


