 "content": "from collections import Counter


def transform(grid):
    """Mark missing cells where a row is an incomplete copy of another row."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    counts = Counter(cell for row in grid for cell in row)
    background = counts.most_common(1)[0][0]
    foreground = max((color for color in counts if color != background),
                     key=lambda color: counts[color])

    out = [row[:] for row in grid]
    masks = [{c for c, value in enumerate(row) if value == foreground}
             for row in grid]
    for r, mask in enumerate(masks):
        if not mask:
            continue
        for other in masks:
            if len(other) > len(mask) and mask < other:
                for c in other - mask:
                    if grid[r][c] == background:
                        out[r][c] = 1
    return out


if __name__ == "__main__":
